INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$457d2f2c$SATQ$, NULL, NULL, $SATQ$028957-DC$SATQ$, $SATQ$disclosed$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Problem-Solving and Data Analysis$SATQ$, $SATQ$Q$SATQ$, $SATQ$Q.C.$SATQ$, $SATQ$One-variable data: Distributions and measures of center and spread$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, NULL, $SATQ$<p class="stem_paragraph ">A data set of 27 different numbers has a mean of 33 and a median of 33. A new data set is created by adding 7 to each number in the original data set that is greater than the median and subtracting 7 from each number in the original data set that is less than the median. Which of the following measures does NOT have the same value in both the original and new data sets?</p>
$SATQ$, $SATQ$[{"id":"a","content":"<p class=\"choice_paragraph \">Median</p>\n"},{"id":"b","content":"<p class=\"choice_paragraph \">Mean</p>\n"},{"id":"c","content":"<p class=\"choice_paragraph \">Sum of the numbers</p>\n"},{"id":"d","content":"<p class=\"choice_paragraph \">Standard deviation</p>\n"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, NULL, $SATQ$<p>Choice D is correct. When a data set has an odd number of elements, the median can be found by ordering the values from least to greatest and determining the middle value. Out of the 27 different numbers in this data set, 13 numbers are below the median, one number is exactly 33, and 13 numbers are above the median. When 7 is subtracted from each number below the median and added to each number above the median, the data spread out from the median. Since the median of this data set, 33, is equivalent to the mean of the data set, the data also spread out from the mean. Since standard deviation is a measure of how spread out the data are from the mean, a greater spread from the mean indicates an increased standard deviation.<p>Choice A is incorrect. All the numbers less than the median decrease and all the numbers greater than the median increase, but the median itself doesn&rsquo;t change. Choices B and C are incorrect. The mean of a data set is found by dividing the sum of the values by the number of values. The net change from subtracting 7 from 13 numbers and adding 7 to 13 numbers is zero. Therefore, neither the mean nor the sum of the numbers changes.</p><p>&nbsp;</p></p>
