8A3.777,3.777,0,0,1,19.317,84.265Z"></path><path d="M19.317,70.408a3.78,3.78,0,1,1-3.778-3.78A3.779,3.779,0,0,1,19.317,70.408Z"></path><path d="M19.317,56.549a3.78,3.78,0,1,1-3.778-3.78A3.776,3.776,0,0,1,19.317,56.549Z"></path><path d="M19.317,42.687a3.78,3.78,0,1,1-3.778-3.78A3.779,3.779,0,0,1,19.317,42.687Z"></path><path d="M19.317,28.828a3.78,3.78,0,1,1-3.778-3.78A3.779,3.779,0,0,1,19.317,28.828Z"></path><path d="M52.272,84.265a3.78,3.78,0,1,1-3.779-3.78A3.777,3.777,0,0,1,52.272,84.265Z"></path><path d="M52.272,70.408a3.78,3.78,0,1,1-3.779-3.78A3.78,3.78,0,0,1,52.272,70.408Z"></path><path d="M52.272,56.549a3.78,3.78,0,1,1-3.779-3.78A3.777,3.777,0,0,1,52.272,56.549Z"></path><path d="M52.272,42.687a3.78,3.78,0,1,1-3.779-3.78A3.78,3.78,0,0,1,52.272,42.687Z"></path><path d="M85.229,84.265a3.78,3.78,0,1,1-3.778-3.78A3.777,3.777,0,0,1,85.229,84.265Z"></path><path d="M85.229,70.408a3.78,3.78,0,1,1-3.778-3.78A3.779,3.779,0,0,1,85.229,70.408Z"></path><path d="M85.229,56.549a3.78,3.78,0,1,1-3.778-3.78A3.776,3.776,0,0,1,85.229,56.549Z"></path><path d="M118.187,84.265a3.78,3.78,0,1,1-3.778-3.78A3.777,3.777,0,0,1,118.187,84.265Z"></path><path d="M118.187,70.408a3.78,3.78,0,1,1-3.778-3.78A3.78,3.78,0,0,1,118.187,70.408Z"></path><path d="M151.141,84.265a3.78,3.78,0,1,1-3.778-3.78A3.777,3.777,0,0,1,151.141,84.265Z"></path></g></svg><div role="region" aria-label="Long description for dot plot titled Data Set A" class="sr-only"><ul>
<li>The data for the dot plot are as follows:<br>
<ul>
<li>22: 5 dots</li>
<li>23: 4 dots</li>
<li>24: 3 dots</li>
<li>25: 2 dots</li>
<li>26: 1 dot</li>
</ul>
</li>
</ul></div></figure></p>
<p style="text-align: left;">The dot plot represents the <math alttext="15"><mn>15</mn>
</math> values in data set A. Data set B is created by adding <math alttext="56"><mn>56</mn>
</math> to each of the values in data set A. Which of the following correctly compares the medians and the ranges of data sets A and B?</p>$SATQ$, $SATQ$[{"id":"be936266-9204-4362-9d3f-5b3852fe2632","content":"<p style=\"text-align: left;\">The median of data set B is equal to the median of data set A, and the range of data set B is equal to the range of data set A.</p>"},{"id":"96100bce-63cc-4c15-9706-2c1351def98a","content":"<p style=\"text-align: left;\">The median of data set B is equal to the median of data set A, and the range of data set B is greater than the range of data set A.</p>"},{"id":"cf8bc4c5-cc54-42a8-ad8e-25d8acc16b6b","content":"<p style=\"text-align: left;\">The median of data set B is greater than the median of data set A, and the range of data set B is equal to the range of data set A.</p>"},{"id":"19dedc90-8bd2-4e28-ba49-40215022f705","content":"<p style=\"text-align: left;\">The median of data set B is greater than the median of data set A, and the range of data set B is greater than the range of data set A.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["cf8bc4c5-cc54-42a8-ad8e-25d8acc16b6b"]$SATQ$::jsonb, $SATQ$<p>Choice C is correct. The median of a data set with an odd number of values, in ascending or descending order, is the middle value of the data set, and the range of a data set is the positive difference between the maximum and minimum values in the data set. Since the dot plot shown gives the values in data set A in ascending order and there are <math alttext="15"><mn>15</mn>
</math> values in the data set, the eighth value in data set A, <math alttext="23"><mn>23</mn>
</math>, is the median. The maximum value in data set A is <math alttext="26"><mn>26</mn>
</math> and the minimum value is <math alttext="22"><mn>22</mn>
</math>, so the range of data set A is <math alttext="26 minus 22"><mn>26</mn><mo>-</mo><mn>22</mn></math>, or <math alttext="4"><mn>4</mn>
</math>. It&rsquo;s given that data set B is created by adding <math alttext="56"><mn>56</mn>
</math> to each of the values in data set A. Increasing each of the <math alttext="15"><mn>15</mn>
</math> values in data set A by <math alttext="56"><mn>56</mn>
</math> will also increase its median value by <math alttext="56"><mn>56</mn>
</math> making the median of data set B <math alttext="79"><mn>79</mn>
</math>. Increasing each value of data set A by <math alttext="56"><mn>56</mn>
</math> does not change the range, since the maximum value of data set B is <math alttext="26 plus 56"><mn>26</mn><mo>+</mo><mn>56</mn></math>, or <math alttext="82"><mn>82</mn>
</math>, and the minimum value is&nbsp;<math alttext="22 plus 56"><mn>22</mn><mo>+</mo><mn>56</mn></math>, or <math alttext="78"><mn>78</mn>
</math>, making the range of data set B <math alttext="82 minus 78"><mn>82</mn><mo>-</mo><mn>78</mn></math>, or <math alttext="4"><mn>4</mn>
</math>. Therefore, the median of data set B is greater than the median of data set A, and the range of data set B is equal to the range of data set A.</p>
<p>Choice A is incorrect and may result from conceptual or calculation errors.</p>
<p>Choice B is incorrect and may result from conceptual or calculation errors.</p>
<p>Choice D is incorrect and may result from conceptual or calculation errors.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, $SATQ$manifold$SATQ$, NULL, NULL, NULL, $SATQ${"questionId":"4626102e","external_id":"f1db57ba-417f-4c96-ae7e-80f171f39606","disclosed_item_id":null,"source":"qbank","vaultid":"0267eb65-1b73-4abf-b909-0b9fffeb01f0","uId":"971ac238-5160-450a-8dbb-f7005873c331","program":"SAT","test_type":2,"test_type_desc":"Math","primary_class_cd":"Q","domain":"Problem-Solving and Data Analysis","skill_cd":"Q.C.","skill_desc":"One-variable data: Distributions and measures of center and spread","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":null,"stem":"<p style=\"text-align: center;\"><figure class='image'><svg xmlns=\"http://www.w3.org/2000/svg\" width=\"162.978\" height=\"124.814\" viewBox=\"0 0 162.978 124.814\" role=\"img\" aria-label=\"A dot plot titled Data Set A. The number line ranges from 22 to 26 in increments of 1. Refer to long description.\"><g id=\"a8978add-b58b-4934-8728-ddf281bf9b2e\" data-name=\"Layer 1\"><line x1=\"162.506\" y1=\"99.205\" x2=\"0.472\" y2=\"99.205\" fill=\"none\" stroke=\"#000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.945\"></line><line x1=\"15.537\" y1=\"93.535\" x2=\"15.537\" y2=\"104.875\" fill=\"none\" stroke=\"#000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.945\"></line><line x1=\"48.492\" y1=\"93.535\" x2=\"48.492\" y2=\"104.875\" fill=\"none\" stroke=\"#000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.945\"></line><line x1=\"81.449\" y1=\"93.535\" x2=\"81.449\" y2=\"104.875\" fill=\"none\" stroke=\"#000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.945\"></line><line x1=\"114.407\" y1=\"93.535\" x2=\"114.407\" y2=\"104.875\" fill=\"none\" stroke=\"#000\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"0.945\"></line><line x1=\"147.361\" y1=\"93.535\" x2=\"147.361\" y2=\"104.875\" fil